<?php $tasks = task_rows($pdo, 't.archived_at IS NOT NULL', [], 't.archived_at DESC'); ?>
<section class="page-heading"><div><p class="eyebrow">STORED AWAY</p><h1>Archive</h1><p class="muted">Tugas yang diarsipkan tetap tersimpan bersama checklist dan catatannya.</p></div></section>
<?php if (!$tasks): ?><div class="panel empty-state list-empty"><span class="empty-icon"><i class="bi bi-archive"></i></span><h3>Arsip masih kosong</h3><p>Arsipkan tugas yang tidak lagi aktif untuk merapikan workspace.</p></div><?php else: ?><div class="task-cards"><?php foreach ($tasks as $task): ?><article class="task-card"><div class="task-card-top"><div><a class="task-card-title" href="index.php?page=task-detail&id=<?= (int)$task['id'] ?>"><?= e($task['title']) ?></a><p class="task-card-description"><?= e($task['description'] ?: 'Tidak ada deskripsi.') ?></p></div><span class="status-pill status-pending"><?= e($task['status']) ?></span></div><div class="task-card-bottom"><div class="task-tags"><span class="category-tag"><?= e($task['category_name'] ?: 'Tanpa kategori') ?></span><small class="muted">Diarsipkan <?= e(date('d M Y', strtotime($task['archived_at']))) ?></small></div><form method="post" action="index.php?page=archive" data-confirm="Pulihkan tugas ini dari arsip?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="task-restore"><input type="hidden" name="id" value="<?= (int)$task['id'] ?>"><input type="hidden" name="return_page" value="archive"><button class="button button-secondary button-small" type="submit"><i class="bi bi-arrow-counterclockwise"></i> Pulihkan</button></form></div></article><?php endforeach; ?></div><?php endif; ?>
